using System.Text; using System.IO; using System.Windows; using Microsoft.Win32; using Ams.UI.Services; using ProMicroProvisioner.Models; using ProMicroProvisioner.Services;
namespace ProMicroProvisioner;
public partial class MainWindow:Window{CancellationTokenSource? cts;public MainWindow(){InitializeComponent();IdentityBox.ItemsSource=IdentityCatalog.All;IdentityBox.SelectedIndex=0;var dropKey=Path.Combine(AppContext.BaseDirectory,"PUT-KEY-HERE","ams_key.h");var legacyKey=Path.Combine(AppContext.BaseDirectory,"firmware","arm28","ams_key.h");var defaultKey=File.Exists(dropKey)?dropKey:legacyKey;if(File.Exists(defaultKey)){KeyBox.Text=defaultKey;Log("ams_key.h خودکار از پوشه PUT-KEY-HERE شناسایی شد.");}else Log("فایل ams_key.h را داخل پوشه PUT-KEY-HERE بینداز یا دستی انتخاب کن.");}void Log(string s)=>Dispatcher.Invoke(()=>{LogBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {s}\r\n");LogBox.ScrollToEnd();});void Apply(IdentityProfile p){ManufacturerBox.Text=p.Manufacturer;ProductBox.Text=p.Product;VidBox.Text=$"0x{p.BootVid:X4}";BootPidBox.Text=$"0x{p.BootPid:X4}";AppPidBox.Text=$"0x{p.AppPid:X4}";SerialBox.Text=p.SerialPrefix+Guid.NewGuid().ToString("N")[..8].ToUpperInvariant();}void IdentityChanged(object s,System.Windows.Controls.SelectionChangedEventArgs e){if(IdentityBox.SelectedItem is IdentityProfile p)Apply(p);}void Random_Click(object s,RoutedEventArgs e){var p=IdentityCatalog.Random();IdentityBox.SelectedItem=p;Apply(p);}void Key_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="ams_key.h|ams_key.h|Header files|*.h"};if(d.ShowDialog()==true)KeyBox.Text=d.FileName;}async void Detect_Click(object s,RoutedEventArgs e){try{PortBox.ItemsSource=null;var hits=await ArduinoIspService.DetectAsync(Log,CancellationToken.None);PortBox.ItemsSource=hits;if(hits.Count>0)PortBox.SelectedIndex=0;Log(hits.Count==0?"No ArduinoISP responder found":$"Found {hits.Count} programmer(s)");}catch(Exception ex){MessageBox.Show(ex.Message,"تشخیص پروگرامر");}}
 async void Install_Click(object s,RoutedEventArgs e){if(cts!=null)return;try{if(PortBox.SelectedItem is not string port)throw new InvalidOperationException("ابتدا پروگرامر را تشخیص بده.");if(!File.Exists(KeyBox.Text))throw new InvalidOperationException("ams_key.h را انتخاب کن.");int vid=BoardHexService.ParseVidPid(VidBox.Text,"VID"),bp=BoardHexService.ParseVidPid(BootPidBox.Text,"Boot PID"),ap=BoardHexService.ParseVidPid(AppPidBox.Text,"App PID");var manuf=BoardHexService.ValidateUsbString(ManufacturerBox.Text,"سازنده");var product=BoardHexService.ValidateUsbString(ProductBox.Text,"محصول");var serial=BoardHexService.ValidateSerial(SerialBox.Text);var profile=new IdentityProfile("custom",manuf,product,"",vid,bp,ap);cts=new();InstallButton.IsEnabled=false;Progress.Value=0;LogBox.Clear();Log("Building ARM 2.8.2 with private local key…");var app=await ArduinoCliService.CompileAsync(KeyBox.Text,profile,Log,cts.Token);var temp=Path.Combine(Path.GetTempPath(),"promicro-identity-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);var baseHex=Path.Combine(AppContext.BaseDirectory,"caterina","Caterina.hex");var patched=BoardHexService.PatchHex(BoardHexService.ParseHex(baseHex),serial,vid,bp,0x02,0,0,product,manuf);var boot=Path.Combine(temp,"Caterina-custom.hex");File.WriteAllText(boot,BoardHexService.ToHex(patched),Encoding.ASCII);var backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"ProMicroBackups",DateTime.Now.ToString("yyyyMMdd-HHmmss"));Log($"Programmer: {port}");Log($"Boot {vid:X4}:{bp:X4} · App {vid:X4}:{ap:X4}");var prog=new Progress<int>(x=>Progress.Value=x);await ArduinoIspService.InstallAsync(port,boot,app,backup,Log,prog,cts.Token);MessageBox.Show($"نصب و Verify کامل شد.\nBackup: {backup}","موفق",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){Log("ERROR: "+ex);MessageBox.Show(ex.Message,"خطا",MessageBoxButton.OK,MessageBoxImage.Error);}finally{cts?.Dispose();cts=null;InstallButton.IsEnabled=true;}}
}
